// cp-trustfulness/artery/dataset-generator/tests/test_cpm_parse.cc
//
// Standalone CPM ASN.1 Parsing and Validation Test
// Tests that CPM generated by Artery's CpService container builder functions
// round-trips through ASN.1 UPER encode/decode and that all fields specified
// in the trace schema (and their optionality) are correctly populated and
// parsed.

#include <artery/envmod/service/CpService.h>
#include <vanetza/asn1/asn1c_wrapper.hpp>
#include <vanetza/asn1/cpm.hpp>

#include <cassert>
#include <cmath>
#include <cstdint>
#include <iostream>
#include <memory>
#include <vector>

using namespace artery;

void test_cpm_population_and_roundtrip() {
    std::cout << "=========================================================\n";
    std::cout << "TEST 1: CPM Container Creation, Validation & Roundtrip\n";
    std::cout << "=========================================================\n";

    // 1. Setup mock VdpSnapshot
    CpService::VdpSnapshot vdp;
    vdp.stationId = 10101;
    vdp.stationType = 5;               // passenger car
    vdp.referenceLatitude = 496100000; // 49.6100000 deg (Luxembourg center)
    vdp.referenceLongitude = 61300000; // 6.1300000 deg
    vdp.orientationAngleDeciDeg = 900; // 90.0 deg (East)
    const uint64_t referenceTimeTaiMs = 1700000000123ULL;

    // 2. Create base CPM (Header + Management Container)
    Cpm message = createCollectivePerceptionMessage(vdp, referenceTimeTaiMs);

    // 3. Add Originating Vehicle Container
    addOriginatingVehicleContainer(message, vdp);

    // 4. Setup Perceived Object Snapshots (testing both fully-populated and
    // optional-absent cases)
    std::vector<CpService::PerceivedObjectSnapshot> perceivedObjects;

    // Object 0: Fully populated (has velocity, sensorIds, etc.)
    {
        CpService::PerceivedObjectSnapshot snap;
        snap.lemId = 42;
        snap.cpsId = 1;
        snap.measurementDeltaTimeMs = 50; // measured 50 ms ago
        snap.xCm = 1550;                  // +15.5 m
        snap.yCm = -2300;                 // -23.0 m
        snap.objectAgeMs = 350;
        snap.objectPerceptionQuality = 5;
        snap.hasVelocity = true;
        snap.speedMps = 14.5;
        snap.headingDeg = 88.0;
        snap.stationType = 5;
        snap.sensorIds = {1, 2}; // radar sensors 1 and 2
        perceivedObjects.push_back(snap);
    }

    // Object 1: Minimally populated (no velocity, no sensorIds)
    {
        CpService::PerceivedObjectSnapshot snap;
        snap.lemId = 99;
        snap.cpsId = 2;
        snap.measurementDeltaTimeMs = 100;
        snap.xCm = -500; // -5.0 m
        snap.yCm = 400;  // +4.0 m
        snap.objectAgeMs = 120;
        snap.objectPerceptionQuality = 3;
        snap.hasVelocity = false; // velocity OPTIONAL absent
        snap.stationType = -1;    // classification OPTIONAL absent
        snap.sensorIds = {};      // sensorIdList OPTIONAL absent
        perceivedObjects.push_back(snap);
    }

    std::vector<std::size_t> selectedIndices = {0, 1};
    omnetpp::SimTime lastTimestamp = omnetpp::SimTime(0.0);

    // 5. Add Perceived Object Container
    addPerceivedObjectContainer(message, perceivedObjects, selectedIndices,
                                lastTimestamp);

    // 6. Validate message
    std::string validateError;
    bool isValid = message.validate(validateError);
    std::cout << "[CHECK] message.validate(): "
                << (isValid ? "PASS" : "FAIL (" + validateError + ")") << "\n";
    assert(isValid);

    // 7. Encode to ASN.1 UPER
    vanetza::ByteBuffer encoded = message.encode();
    std::cout << "[CHECK] message.encode() size: " << encoded.size()
                << " bytes\n";
    assert(!encoded.empty());

    // 8. Decode back into a new Cpm instance
    Cpm decodedCpm;
    bool decodeSuccess = decodedCpm.decode(encoded);
    std::cout << "[CHECK] decodedCpm.decode(): "
                << (decodeSuccess ? "PASS" : "FAIL") << "\n";
    assert(decodeSuccess);

    // 9. Verify Header & Management Container
    std::cout << "\n--- Verifying Management Container ---\n";
    const auto &header = decodedCpm->header;
    std::cout << "[CHECK] header.stationId: " << header.stationId << " (expected "
                << vdp.stationId << ")\n";
    assert(header.stationId == vdp.stationId);
    assert(header.protocolVersion == 2);
    assert(header.messageId == Vanetza_ITS2_MessageId_cpm);

    const auto &mc = decodedCpm->payload.managementContainer;
    uint64_t decodedRefTime = 0;
    int refTimeRet = asn_INTEGER2uint64(&mc.referenceTime, &decodedRefTime);
    assert(refTimeRet == 0);
    std::cout << "[CHECK] mc.referenceTime: " << decodedRefTime << " (expected "
                << referenceTimeTaiMs << ")\n";
    assert(decodedRefTime == referenceTimeTaiMs);

    double decodedLat = mc.referencePosition.latitude / 1e7;
    double decodedLon = mc.referencePosition.longitude / 1e7;
    std::cout << "[CHECK] mc.referencePosition (lat, lon): (" << decodedLat
                << ", " << decodedLon << ")\n";
    assert(mc.referencePosition.latitude == vdp.referenceLatitude);
    assert(mc.referencePosition.longitude == vdp.referenceLongitude);

    // 10. Verify Wrapped CPM Containers
    std::cout << "\n--- Verifying CPM Containers ---\n";
    const auto &containers = decodedCpm->payload.cpmContainers.list;
    std::cout << "[INFO] Number of wrapped containers: " << containers.count
                << "\n";
    assert(containers.count == 2); // OVC + POC

    bool foundOvc = false;
    bool foundPoc = false;

    for (int i = 0; i < containers.count; ++i) {
        const auto *wcc = containers.array[i];
        assert(wcc != nullptr);

        if (wcc->containerId ==
                Vanetza_ITS2_CpmContainerId_originatingVehicleContainer &&
            wcc->containerData.present ==
                Vanetza_ITS2_WrappedCpmContainer__containerData_PR_OriginatingVehicleContainer) {
        foundOvc = true;
        const auto &ovc = wcc->containerData.choice.OriginatingVehicleContainer;
        double headingDeg = ovc.orientationAngle.value / 10.0;
        std::cout << "[CHECK] OVC orientationAngle: " << headingDeg
                    << " deg (expected 90.0 deg)\n";
        assert(ovc.orientationAngle.value == vdp.orientationAngleDeciDeg);

        // CRUCIAL FINDING VERIFICATION:
        // Does OVC have speed in ETSI TS 103 324 v2.1.1?
        // In ETSI TS 103 324 v2.1.1 OriginatingVehicleContainer, only
        // orientationAngle, pitchAngle (OPTIONAL), rollAngle (OPTIONAL),
        // trailerDataSet (OPTIONAL) exist. Speed does NOT exist in OVC ASN.1!
        std::cout << "[NOTE] OriginatingVehicleContainer conforms to TS 103 324 "
                    "v2.1.1: speed is NOT an OVC field.\n";
        } else if (
            wcc->containerId ==
                Vanetza_ITS2_CpmContainerId_perceivedObjectContainer &&
            wcc->containerData.present ==
                Vanetza_ITS2_WrappedCpmContainer__containerData_PR_PerceivedObjectContainer) {
        foundPoc = true;
        const auto &poc = wcc->containerData.choice.PerceivedObjectContainer;
        std::cout << "[CHECK] POC numberOfPerceivedObjects: "
                    << poc.numberOfPerceivedObjects
                    << ", list.count: " << poc.perceivedObjects.list.count << "\n";
        assert(poc.numberOfPerceivedObjects == 2);
        assert(poc.perceivedObjects.list.count == 2);

        // Object 0 (Fully Populated)
        const auto *po0 = poc.perceivedObjects.list.array[0];
        assert(po0 != nullptr);
        assert(po0->objectId != nullptr);
        std::cout << "[CHECK] Obj 0 objectId: " << *(po0->objectId)
                    << " (expected 1)\n";
        assert(*(po0->objectId) == 1);

        std::cout << "[CHECK] Obj 0 measurementDeltaTime: "
                    << po0->measurementDeltaTime << " ms (expected 50)\n";
        assert(po0->measurementDeltaTime == 50);

        double obj0_x = po0->position.xCoordinate.value / 100.0;
        double obj0_y = po0->position.yCoordinate.value / 100.0;
        std::cout << "[CHECK] Obj 0 rel pos (x, y): (" << obj0_x << " m, "
                 << obj0_y << " m)\n";
        assert(po0->position.xCoordinate.value == 1550);
        assert(po0->position.yCoordinate.value == -2300);

        // Check velocity (present)
        assert(po0->velocity != nullptr);
        assert(po0->velocity->present == Vanetza_ITS2_Velocity3dWithConfidence_PR_polarVelocity);
        const auto &polar = po0->velocity->choice.polarVelocity;
        double obj0_speed = polar.velocityMagnitude.speedValue / 100.0;
        double obj0_heading = polar.velocityDirection.value / 10.0;
        std::cout << "[CHECK] Obj 0 polar velocity: speed = " << obj0_speed
                    << " m/s (expected 14.5), heading = " << obj0_heading
                    << " deg (expected 88.0)\n";
        assert(std::abs(obj0_speed - 14.5) < 0.01);
        assert(std::abs(obj0_heading - 88.0) < 0.1);

        // Check sensorIdList (present)
        assert(po0->sensorIdList != nullptr);
        std::cout << "[CHECK] Obj 0 sensorIdList count: "
                    << po0->sensorIdList->list.count << " (expected 2)\n";
        assert(po0->sensorIdList->list.count == 2);
        assert(*(po0->sensorIdList->list.array[0]) == 1);
        assert(*(po0->sensorIdList->list.array[1]) == 2);

        // Object 1 (Minimally Populated - Optional fields absent)
        const auto *po1 = poc.perceivedObjects.list.array[1];
        assert(po1 != nullptr);
        assert(po1->objectId != nullptr);
        std::cout << "[CHECK] Obj 1 objectId: " << *(po1->objectId)
                    << " (expected 2)\n";
        assert(*(po1->objectId) == 2);

        double obj1_x = po1->position.xCoordinate.value / 100.0;
        double obj1_y = po1->position.yCoordinate.value / 100.0;
        std::cout << "[CHECK] Obj 1 rel pos (x, y): (" << obj1_x << " m, "
                    << obj1_y << " m)\n";
        assert(po1->position.xCoordinate.value == -500);
        assert(po1->position.yCoordinate.value == 400);

        // Check velocity (OPTIONAL absent)
        std::cout << "[CHECK] Obj 1 velocity pointer: "
                    << (po1->velocity == nullptr ? "nullptr (PASS, absent)" : "NOT NULL (FAIL)")
                    << "\n";
        assert(po1->velocity == nullptr);

        // Check sensorIdList (OPTIONAL absent)
        std::cout << "[CHECK] Obj 1 sensorIdList pointer: "
                    << (po1->sensorIdList == nullptr ? "nullptr (PASS, absent)" : "NOT NULL (FAIL)")
                    << "\n";
        assert(po1->sensorIdList == nullptr);

        // Check classification (OPTIONAL absent)
        std::cout << "[CHECK] Obj 1 classification pointer: "
                    << (po1->classification == nullptr ? "nullptr (PASS, absent)" : "NOT NULL (FAIL)")
                    << "\n";
        assert(po1->classification == nullptr);
        }
    }

    assert(foundOvc);
    assert(foundPoc);

    std::cout
        << "\n>>> TEST 1 RESULT: ALL CPM PARSE & ROUNDTRIP CHECKS PASSED <<<\n\n";
}

int main() {
    omnetpp::cStaticFlag csf;
    omnetpp::SimTime::setScaleExp(-9);

    try {
        test_cpm_population_and_roundtrip();
        std::cout << "CPM ASN.1 parsing validation completed successfully!\n";
        return 0;
    } catch (const std::exception &e) {
        std::cerr << "[ERROR] Exception caught in test_cpm_parse: " << e.what() << "\n";
        return 1;
    }
}

